#pragma once
#include "../Source/HeadOrbit.h"
void headOrbitChecks(){
 for(double sr:{44100.,48000.,96000.,192000.}){cortex::HeadOrbit right,left;right.reset(sr,0);left.reset(sr,8);int firstNear=-1,firstFar=-1;double nearEnergy=0,farEnergy=0;for(int i=0;i<512;++i){auto a=right.process(i==0?1.f:0.f,0,1),b=left.process(i==0?1.f:0.f,0,1);require(std::isfinite(a.left)&&std::isfinite(a.right),"finite orbit impulse");if(std::abs(a.right)>1e-6&&firstNear<0)firstNear=i;if(std::abs(a.left)>1e-6&&firstFar<0)firstFar=i;nearEnergy+=a.right*a.right;farEnergy+=a.left*a.left;require(std::abs(a.left-b.right)<.0002f&&std::abs(a.right-b.left)<.0002f,"opposite orbit direction swaps ears");}require(firstNear==0&&firstFar>=int(sr*.00065)-1&&firstFar<=int(sr*.00065)+1&&nearEnergy>farEnergy,"fractional ITD and ILD direction");right.clear();for(int i=0;i<512;++i){auto x=right.process(0,.5f,1);require(x.left==0&&x.right==0,"orbit delay clears");}}
 cortex::HeadOrbit front,rear;front.reset(48000,12);rear.reset(48000,4);double bright=0,dark=0;for(int i=0;i<2048;++i){float signal=std::sin(i*2*cortex::pi*9000/48000);auto a=front.process(signal,0,1),b=rear.process(signal,0,1);bright+=a.left*a.left;dark+=b.left*b.left;}require(dark<bright*.65,"rear spectral cue attenuates high frequencies");
 CortexProcessor p;require(p.param("orbitEnabled")==0&&std::abs(p.param("orbitRate")-.07f)<.0001&&std::abs(p.param("orbitDepth")-.7f)<.002,"orbit defaults");juce::MidiBuffer midi;set(p,"reverb",0);set(p,"orbitEnabled",1);set(p,"binaural",1);set(p,"orbitRate",.5f);set(p,"orbitDepth",1);set(p,"play",1);set(p,"output",1);for(double sr:{44100.,48000.,96000.,192000.})for(int cap=0;cap<3;++cap){set(p,"voices",float(cap));p.prepareToPlay(sr,256);require(render(p,80,midi)>0,"orbit stress audible");require(p.activeVoices.load()<=(4<<cap),"orbit obeys voice cap");}set(p,"field",0);render(p,800,midi);require(render(p,30,midi)==0,"orbit pause silence");juce::MemoryBlock data;p.getStateInformation(data);CortexProcessor q;q.setStateInformation(data.getData(),int(data.getSize()));require(q.param("orbitEnabled")==1&&std::abs(q.param("orbitRate")-.5f)<.001&&q.param("orbitDepth")==1,"orbit host state recall");auto old=p.state.copyState();for(int i=old.getNumChildren()-1;i>=0;--i)if(old.getChild(i).getProperty("id").toString().startsWith("orbit"))old.removeChild(i,nullptr);auto xml=old.createXml();juce::MemoryBlock legacy;juce::AudioProcessor::copyXmlToBinary(*xml,legacy);q.setStateInformation(legacy.getData(),int(legacy.getSize()));require(q.param("orbitEnabled")==0&&std::abs(q.param("orbitRate")-.07f)<.001&&std::abs(q.param("orbitDepth")-.7f)<.002,"old DAW sessions reset orbit defaults");auto& parameters=p.getParameters();require(parameters.size()==34,"three appended parameters");for(int i=0;i<3;++i)require(dynamic_cast<juce::AudioProcessorParameterWithID*>(parameters[31+i])->paramID==juce::StringArray{"orbitEnabled","orbitRate","orbitDepth"}[i],"new host parameters appended in order");require(allocationCount==0,"orbit callback no allocation");std::cout<<"PASS Head Orbit ear timing/direction/rear cue, reset, 44.1/48/96/192kHz cap stress, pause/state/noalloc\n";
}
